/bin/bash -lc "python3 - <<'PY'
import re
import subprocess
patch = subprocess.check_output(['git', 'diff', '--unified=0'], text=True)
path = None
line_no = None
bad = []
for line in patch.splitlines():
    if line.startswith('+++ b/'):
        path = line[6:]
    elif line.startswith('@@'):
        match = re.search(r'\\+(\\d+)', line)
        line_no = int(match.group(1)) if match else None
    elif line.startswith('+') and not line.startswith('+++'):
        if len(line[1:]) > 100:
            bad.append((path, line_no, len(line[1:])))
        if line_no is not None:
            line_no += 1
    elif not line.startswith('-') and line_no is not None:
        line_no += 1
if bad:
    for row in bad:
        print('%s:%s:%s' % row)
    raise SystemExit(1)
print('changed added lines: <= 100 characters')
PY"

